/**
 * rail — the fixtures both rail slices mount: #2946 (left rail: acting
 * profile, signed-out state, groups) and #2947 (right rail: suggestions,
 * events, overflow). One module because the left- and right-rail tickets
 * share the same "See all past N rows" overflow contract and the same
 * viewer-identity axis (an acting profile vs. none at all) that the
 * suggestion rows must read correctly against either way.
 *
 * Nothing here fetches; every timestamp is an absolute ISO 8601 string, per
 * this package's "no `Date.now()` / `new Date()` at module scope" rule (see
 * `types/porchPost.ts`). `FeedRoute`-style routes/cards render these
 * directly until #2869 swaps the source for a real hook without touching
 * any component's props.
 *
 * `PORCH_RAIL_SEE_ALL_LIMIT` is the "fits without a See all" row count every
 * "overflow" fixture below is sized to exceed — see `rail.test.ts` for the
 * invariant that keeps that true.
 *
 * Coverage, by ticket:
 *   #2946 (left rail)
 *     - `PORCH_RAIL_PROFILE_SIGNED_IN` / `PORCH_ACTING_PROFILE` — the acting
 *       profile: avatar, display name, friend count.
 *     - `PORCH_RAIL_PROFILE_SIGNED_OUT` — the signed-out state (pairs with
 *       the existing `porch_profile_signed_out` copy).
 *     - `PORCH_GROUPS_EMPTY` / `PORCH_GROUPS_FEW` (3, "fits") /
 *       `PORCH_GROUPS_OVERFLOW` (6, "more-than-fits") — the three group-list
 *       sizes the ticket names.
 *   #2947 (right rail)
 *     - `PORCH_SUGGESTION_ZERO_MUTUALS` / `_SOME_MUTUALS` / `_MANY_MUTUALS`
 *       — the zero/some/many mutual-friend axis, as individual rows and
 *       folded into `PORCH_SUGGESTIONS_FEW` / `_OVERFLOW`.
 *     - `PORCH_SUGGESTION_NO_VIEWER` — the row that must read correctly
 *       with no acting viewer at all; pair it with
 *       `PORCH_RAIL_PROFILE_SIGNED_OUT` in a test. Its mutual count is 0,
 *       same shape as `PORCH_SUGGESTION_ZERO_MUTUALS` — a bare count needs
 *       no "you" to read correctly, which is what makes it viewer-safe.
 *     - `PORCH_EVENTS_EMPTY` / `PORCH_EVENTS_FEW` (2) / `PORCH_EVENTS_OVERFLOW`
 *       (5) — the zero/few/many event-list sizes the ticket names.
 *     - `PORCH_GROUPS_OVERFLOW` / `PORCH_SUGGESTIONS_OVERFLOW` /
 *       `PORCH_EVENTS_OVERFLOW` each independently satisfy "a card whose
 *       rows overflow past the See-all threshold" — pick whichever card is
 *       under test.
 *
 * No row below sets `avatarUrl` — none of the previously-referenced
 * `/fixtures/porch/*.png` assets exist in this repo (that was showing as a
 * broken-image glyph on the live page), so every row here exercises
 * `PorchAvatar`'s monogram fallback instead. Same rule as `posts.ts`'s
 * `authorAvatarUrl` note.
 */

import type {
  PorchActingProfile,
  PorchEventSummary,
  PorchGroupSummary,
  PorchRailProfileState,
  PorchSuggestionRow,
} from "../types/porchRail";

/**
 * The row count every rail card shows before a "See all" affordance takes
 * over. Shared by groups, suggestions and events so the three cards behave
 * consistently; `PorchRailCard`'s overflow logic (#2947) should read this
 * constant rather than hardcode its own copy of it.
 */
export const PORCH_RAIL_SEE_ALL_LIMIT = 3;

// ---------------------------------------------------------------------------
// Acting profile (#2946)
// ---------------------------------------------------------------------------

export const PORCH_ACTING_PROFILE: PorchActingProfile = {
  displayName: "Jordan Ashworth",
  friendCount: 214,
};

export const PORCH_RAIL_PROFILE_SIGNED_IN: PorchRailProfileState = {
  state: "signed_in",
  profile: PORCH_ACTING_PROFILE,
};

export const PORCH_RAIL_PROFILE_SIGNED_OUT: PorchRailProfileState = {
  state: "signed_out",
};

// ---------------------------------------------------------------------------
// Groups (#2946) — zero, three ("fits"), more-than-fits
// ---------------------------------------------------------------------------

export const PORCH_GROUPS_EMPTY: readonly PorchGroupSummary[] = [];

export const PORCH_GROUPS_FEW: readonly PorchGroupSummary[] = [
  {
    id: "group-1",
    name: "Riverside Book Club",
    hasUnread: true,
    unreadCount: 32,
  },
  {
    id: "group-2",
    name: "Trailhead Hikers",
    hasUnread: false,
  },
  {
    id: "group-3",
    name: "Neighborhood Watch",
    hasUnread: false,
  },
];

export const PORCH_GROUPS_OVERFLOW: readonly PorchGroupSummary[] = [
  ...PORCH_GROUPS_FEW,
  { id: "group-4", name: "Community Garden Crew", hasUnread: true, unreadCount: 8 },
  // hasUnread true with no unreadCount: the "count genuinely unknown" case,
  // which YourGroupsCard falls back to porch_group_unread_label's static
  // text for rather than fabricating a number.
  { id: "group-5", name: "Weekend Woodworkers", hasUnread: true },
  {
    id: "group-6",
    name: "Porch Pancake Breakfast",
    hasUnread: true,
    unreadCount: 2,
  },
];

// ---------------------------------------------------------------------------
// People you may know (#2947) — zero / some / many mutuals, plus the
// no-viewer case
// ---------------------------------------------------------------------------

export const PORCH_SUGGESTIONS_EMPTY: readonly PorchSuggestionRow[] = [];

export const PORCH_SUGGESTION_ZERO_MUTUALS: PorchSuggestionRow = {
  id: "suggestion-zero",
  name: "Elena Vasquez",
  mutualFriendsCount: 0,
};

/**
 * The row #2947 requires to "read correctly when there is no viewer at
 * all". Render it under `PORCH_RAIL_PROFILE_SIGNED_OUT` — a bare mutual
 * count has nothing viewer-relative to say, so it stays correct with no
 * acting profile in scope. Kept as its own named export (rather than reusing
 * `PORCH_SUGGESTION_ZERO_MUTUALS` silently) so a test can point at the exact
 * fixture the no-viewer scenario is asserting against.
 */
export const PORCH_SUGGESTION_NO_VIEWER: PorchSuggestionRow = {
  id: "suggestion-no-viewer",
  name: "Sam Whitfield",
  // undefined (not 0): no acting viewer, so mutuals are unknowable — distinct
  // from PORCH_SUGGESTION_ZERO_MUTUALS' real, computed zero. See
  // `types/porchRail.ts`'s `PorchSuggestionRow.mutualFriendsCount` doc.
  mutualFriendsCount: undefined,
};

export const PORCH_SUGGESTION_SOME_MUTUALS: PorchSuggestionRow = {
  id: "suggestion-some",
  name: "Priya Natarajan",
  mutualFriendsCount: 4,
};

export const PORCH_SUGGESTION_MANY_MUTUALS: PorchSuggestionRow = {
  id: "suggestion-many",
  name: "Marcus Webb",
  mutualFriendsCount: 37,
