export const PORCH_SUGGESTIONS_FEW: readonly PorchSuggestionRow[] = [
  PORCH_SUGGESTION_ZERO_MUTUALS,
  PORCH_SUGGESTION_SOME_MUTUALS,
];

export const PORCH_SUGGESTIONS_OVERFLOW: readonly PorchSuggestionRow[] = [
  PORCH_SUGGESTION_ZERO_MUTUALS,
  PORCH_SUGGESTION_SOME_MUTUALS,
  PORCH_SUGGESTION_MANY_MUTUALS,
