// ---------------------------------------------------------------------------
// Upcoming events (#2947) — zero / few / many
// ---------------------------------------------------------------------------

export const PORCH_EVENTS_EMPTY: readonly PorchEventSummary[] = [];

export const PORCH_EVENTS_FEW: readonly PorchEventSummary[] = [
