/**
 * search — the fixtures `PorchSearch` (recent-query list) and `SearchRoute`
 * (results surface) mount for #2945. Nothing here fetches; every timestamp
 * is an absolute ISO 8601 string, per this package's "no `Date.now()` /
 * `new Date()` at module scope" rule (see `types/porchPost.ts`).
 * `SearchRoute` renders these directly until #2869 swaps the source for a
 * real hook without touching any component's props.
 *
 * Post hits reuse `PORCH_POST_FIXTURES` (`fixtures/posts.ts`) rather than
 * inventing a second set of post content — a search hit renders through the
 * same `PorchPostCard` the feed does, so the same fixtures exercise both.
 *
 * No `avatarUrl` values on the people hits — `/fixtures/porch/*.png` paths
 * do not exist on disk in this repo, so pointing at one rendered as a
 * broken-image glyph instead of a real photo. Each hit omits the field
 * (not an empty string) so `PorchAvatar` falls through to its initials
 * monogram.
 *
 * Coverage:
 *   - `PORCH_RECENT_QUERIES` — the recent-query list `PorchSearch` shows.
 *   - `PORCH_SEARCH_RESULTS_WITH_HITS` — a query with both post and people
 *     hits.
 *   - `PORCH_SEARCH_RESULTS_NO_RESULTS` — a query that yields no results
 *     (both arrays empty, `query` still populated — distinct from
 *     `SearchRoute`'s own "no query at all" state, which is a route-level
 *     concern with nothing to fixture).
 */

import { PORCH_POST_FIXTURES } from "./posts";
import type {
  PorchPersonSearchHit,
  PorchRecentQuery,
  PorchSearchResults,
} from "../types/porchSearch";

export const PORCH_RECENT_QUERIES: readonly PorchRecentQuery[] = [
