  },
  {
    id: "recent-2",
    // Exact-matches `PORCH_SEARCH_RESULTS_WITH_HITS.query` below so this
    // chip is the one recent-query entry that demonstrates the
    // populated-results branch of `SearchRoute`'s fixture lookup
    // (`RESULTS_BY_QUERY` does an exact-string `Map.get`, not a substring
    // match — "riverside book club" never matched it).
    query: "riverside",
    searchedAt: "2026-09-09T21:10:00Z",
  },
  {
    id: "recent-3",
    query: "Marcus Webb",
    searchedAt: "2026-09-08T13:40:00Z",
  },
];

export const PORCH_PEOPLE_SEARCH_HITS: readonly PorchPersonSearchHit[] = [
  {
    id: "hit-person-1",
    name: "Priya Natarajan",
    mutualFriendsCount: 4,
  },
  {
    id: "hit-person-2",
    name: "Marcus Webb",
    mutualFriendsCount: 1,
  },
  {
    id: "hit-person-3",
    name: "The Riverside Book Club",
    // No mutual-friend context at all for a Page/Group-shaped hit — omitted,
    // not zero.
