/**
 * composerAvailability — the attachment-tab availability matrix
 * `PorchAttachmentTray` (#2944) renders from. Nothing here fetches; this is
 * a plain data module, no side effects.
 *
 * `PORCH_COMPOSER_AVAILABILITY_DEFAULT` is the one constant a real route
 * should import: it is today's ground truth (all four tabs unavailable,
 * since none of #2822/#2825/#2826/#2823 has landed). Each of those tickets
 * lands by flipping exactly ONE flag in this object — never by editing
 * `PorchAttachmentTray` itself, which is the point of routing availability
 * through a fixture in the first place.
 *
 * `porchComposerAvailability` is a pure builder (no fetching, no module-scope
 * side effects — it's a plain function, not a stateful call) so a test can
 * drive any combination without hand-writing all sixteen matrices; the four
 * single-flag exports below name the specific combination each landing
 * ticket needs.
 *
 * Coverage:
 *   - `PORCH_COMPOSER_AVAILABILITY_DEFAULT` — today's real-world default,
 *     all four tabs unavailable.
 *   - `PORCH_COMPOSER_AVAILABILITY_ALL_AVAILABLE` — every tab available, for
 *     the "fully landed" end state.
 *   - `PORCH_COMPOSER_AVAILABILITY_PHOTO_AVAILABLE` (#2822),
 *     `_VIDEO_AVAILABLE` (#2825), `_POLL_AVAILABLE` (#2826),
 *     `_FEELING_AVAILABLE` (#2823) — each flips exactly the one tab its
 *     ticket lands, all others left at the default's `false`.
 */

import type {
  PorchAttachmentKind,
  PorchComposerAvailability,
} from "../types/composerAvailability";

const ALL_UNAVAILABLE: PorchComposerAvailability = {
  photo: { available: false },
  video: { available: false },
  poll: { available: false },
  feeling: { available: false },
};

/**
 * Builds a full four-tab matrix, defaulting every tab to unavailable and
 * flipping only the kinds named in `available` on. Lets a test (or a future
 * slice, before it settles on editing the named export directly) drive any
 * combination without hand-writing a new object literal.
 */
export function porchComposerAvailability(
  available: readonly PorchAttachmentKind[] = [],
): PorchComposerAvailability {
  const flipped = new Set(available);
  return {
    photo: { available: flipped.has("photo") },
    video: { available: flipped.has("video") },
    poll: { available: flipped.has("poll") },
    feeling: { available: flipped.has("feeling") },
  };
}

/** Today's real-world default: no attachment slice has landed yet. */
export const PORCH_COMPOSER_AVAILABILITY_DEFAULT: PorchComposerAvailability = ALL_UNAVAILABLE;

/** Every tab available — the fully-landed end state. */
export const PORCH_COMPOSER_AVAILABILITY_ALL_AVAILABLE: PorchComposerAvailability =
  porchComposerAvailability(["photo", "video", "poll", "feeling"]);

/** #2822 lands by flipping only `photo` on. */
export const PORCH_COMPOSER_AVAILABILITY_PHOTO_AVAILABLE: PorchComposerAvailability =
