/** #2825 lands by flipping only `video` on. */
export const PORCH_COMPOSER_AVAILABILITY_VIDEO_AVAILABLE: PorchComposerAvailability =
  porchComposerAvailability(["video"]);

/** #2826 lands by flipping only `poll` on. */
export const PORCH_COMPOSER_AVAILABILITY_POLL_AVAILABLE: PorchComposerAvailability =
  porchComposerAvailability(["poll"]);

/** #2823 lands by flipping only `feeling` on. */
export const PORCH_COMPOSER_AVAILABILITY_FEELING_AVAILABLE: PorchComposerAvailability =
  porchComposerAvailability(["feeling"]);


